//! Every command mnml-zig knows about — 795 Rust ids plus 140 Zig-only, titles, palette groups
//! and default chords per keymap profile (D4b). Data only: no function
//! pointers. Runners live in each subsystem's `pub const table` and are
//! merged into `command.runners` at comptime.
//!
//! GENERATED from the Rust registry's `builtin_commands()` by a throwaway
//! script on 2026-09-04, then split into profiles by the rules in
//! `docs/KEYMAP_PROFILES.md`. Edit by hand from here on — the script is
//! gone on purpose; this file is now the source of truth.
//!
//! Profile rules applied (spike scope):
//!   * Rust defaults land in `both`.
//!   * Chords the vim editor must receive raw — `ctrl+w/g/d/u/e/y/r/n/h/j/t/f`
//!     and the `ctrl+k …` menus — are `standard` only.
//!   * `ctrl+]` / `ctrl+[` indent / outdent in `standard`; `bracket_match` keeps
//!     `ctrl+]` in `vim`.
//!   * NvChad leader menus and Neovim LSP chords on the `vim` side.
//! TODO(D4b): full NvChad derivation — Phase 1.

const std = @import("std");
const builtin = @import("builtin");

pub const Keys = struct {
    vim: []const []const u8 = &.{},
    standard: []const []const u8 = &.{},
    both: []const []const u8 = &.{},
    /// Chords the vim handler answers itself — its `Ctrl-W` prefix, which
    /// the keymap must never bind (rule 1 of `docs/KEYMAP_PROFILES.md`).
    /// Shown by the cheatsheet, the palette and the hover copy in the vim
    /// profile; never bound. `input/vim.zig` pins each to its command.
    vim_handler: []const []const u8 = &.{},
};

pub const Spec = struct {
    id: [:0]const u8,
    title: []const u8,
    group: []const u8,
    keys: Keys = .{},
};

/// `nav.back` / `nav.forward` are platform-split: macOS terminals consume
/// `alt+left` / `alt+right` for word motion, so the arrows are Linux/Windows
/// only. The `minus` spellings are the only nav chords on macOS.
const nav_back_keys: []const []const u8 = if (builtin.os.tag == .macos) &.{"ctrl+minus"} else &.{ "alt+left", "ctrl+minus" };
const nav_forward_keys: []const []const u8 = if (builtin.os.tag == .macos) &.{ "ctrl+shift+minus", "ctrl+underscore" } else &.{ "alt+right", "ctrl+shift+minus", "ctrl+underscore" };

