test "1135 specs, unique ids" {
    // 797 Rust ids + the eight Zig-only menu commands + seven git row commands
    // + four script commands + the SCRIPTS activity command + eight cutover-prep commands + four var
    // commands + three HTTP panel commands + six Playwright commands
    // + eighteen file-manager commands + four TODOS row commands
    // + three NOTES row commands + four FINDINGS row commands + ten
    // SESSIONS commands + six dock commands + two lsp-more commands.
    // SESSIONS commands + six dock commands + two diff-view commands
    // + three browse commands (file / line / commit on the remote)
    // + nine ui-polish commands + `view.only`.
    // + eight SEARCH row commands + the menu bar's summon + two coverage
    // chip commands + three in-progress operation commands + eleven
    // rebase-plan / amend / reset commands.
    // + four diff-any-two-refs commands + eight branch verbs + seven
    // stash commands + two command-log commands + two detail-row
    // commands (git-more2) + three launcher-pin commands
    // + `view.reset_layout` + the session-worktree launch and its three
    // row verbs (open in tree / merge / remove) + `view.focus_top` /
    // `focus_bottom` / `focus_previous` (vim Ctrl-W t / b / p)
    // + the SESSIONS history chip's two verbs (sessions-card)
    // + six SEARCH section commands (refresh / open / open_split /
    // copy_path / copy_line / open_pane)
    // + `integrations.dismiss_toml_notice` (the 0.2 manifests notice)
    // + `app.command_line` (the bottom row's `:` line) and
    // `toast.run_action` (bottom-row).
    // + the launcher dock's six (`view.dock_*`, `view.focus_dock`)
    // and the two `integrations.*_dock` pin verbs (launcher-dock)
    // + `view.menu_bar_pin` (menu-bar-pin)
    // + `integrations.update` (int-distribution)
    // + `editor.lsp_this_file` (the `editor.lsp_max_bytes` override)
    // + the five `ai.copilot_*` verbs (the Copilot ghost-text backend)
    // + `view.claude_mark_custom` (claude-icon) in place of
    // `integrations.edit_claude_glyph`, which was a cut command a menu
    // row still fired — a swap, so the count did not move.
    // + the three `view.rail_*` membership commands (railmove)
    // + the four `view.dock_item_move_*` reorder commands (dock-polish)
    // + `view.focus_prev_split`, the split walk backwards (splitcycle)
    try std.testing.expectEqual(@as(usize, 1135), specs.len);
    // + the four named-layout commands, `layout.save` / `load` / `delete` / `pick` (layouts)
    try std.testing.expectEqual(@as(usize, 1135), specs.len);
    // + `jobs.show`, the background-jobs list (jobschip)
    try std.testing.expectEqual(@as(usize, 1135), specs.len);
    // + `editor.toggle_indent_guides` (editorpolish)
    try std.testing.expectEqual(@as(usize, 1135), specs.len);
    // + `editor.toggle_indent_guides`, `git.toggle_line_blame` (editorpolish)
    try std.testing.expectEqual(@as(usize, 1135), specs.len);
    // + `sessions.sort_waiting`, the Waiting axis (needsyou)
    try std.testing.expectEqual(@as(usize, 1135), specs.len);
    // + `sessions.sort_waiting`, the Waiting axis, and
    //   `sessions.next_waiting` / `prev_waiting`, the jumps (needsyou)
    try std.testing.expectEqual(@as(usize, 1135), specs.len);
    // + `term.search` / `term.search_next` / `term.search_prev` (scrollsearch)
    try std.testing.expectEqual(@as(usize, 1135), specs.len);
    // Uniqueness is enforced at comptime by command.zig; this pins the count.
}
